import { resolveElementColor } from '@progress/kendo-drawing';
const elementStyles = (element) => element.ownerDocument.defaultView.getComputedStyle(element);
const getProp = (element, prop) => elementStyles(element).getPropertyValue(prop);
let colorCache;
const getColorProp = (element, prop) => {
    const value = getProp(element, prop);
    if (!value) {
        return undefined;
    }
    if (!colorCache) {
        colorCache = new Map();
    }
    let color;
    if (colorCache.has(value)) {
        color = colorCache.get(value);
    }
    else {
        color = resolveElementColor(element, prop);
        colorCache.set(value, color);
    }
    return color;
};
export const loadTheme = (element) => {
    const primaryBg = getColorProp(element, '--kendo-chart-primary-bg');
    const primaryContrast = getColorProp(element, '--kendo-chart-primary-contrast');
    const normalTextColor = getColorProp(element, '--kendo-chart-text');
    const normalBackground = getColorProp(element, '--kendo-color-surface');
    const selectionColor = '#0B99FF';
    return {
        shapeDefaults: {
            fill: {
                color: primaryBg
            },
            content: {
                color: primaryContrast
            },
            connectorDefaults: {
                fill: {
                    color: selectionColor
                },
                stroke: {
                    color: primaryContrast
                },
                hover: {
                    fill: {
                        color: selectionColor
                    },
                    stroke: {
                        color: selectionColor
                    }
                }
            }
        },
        editable: {
            resize: {
                handles: {
                    width: 10,
                    height: 10,
                    stroke: {
                        color: selectionColor
                    },
                    fill: {
                        color: normalBackground
                    },
                    hover: {
                        stroke: {
                            color: selectionColor
                        },
                        fill: {
                            color: selectionColor
                        }
                    }
                }
            }
        },
        selectable: {
            stroke: {
                color: selectionColor
            }
        },
        connectionDefaults: {
            stroke: {
                color: normalTextColor
            },
            content: {
                color: normalTextColor,
                bgColor: primaryContrast
            },
            selection: {
                handles: {
                    fill: {
                        color: primaryContrast
                    },
                    stroke: {
                        color: normalTextColor
                    },
                    width: 8,
                    height: 8
                },
                stroke: {
                    color: normalTextColor
                }
            },
            editable: {
                points: {
                    midpoint: {
                        fill: {
                            color: selectionColor
                        },
                        stroke: {
                            color: primaryContrast,
                            width: 1
                        },
                        radius: 4,
                    },
                    vertex: {
                        fill: {
                            color: primaryContrast
                        },
                        stroke: {
                            color: selectionColor,
                            width: 2
                        },
                        radius: 3
                    }
                }
            }
        }
    };
};
